using System.Text.Json;using WAID.Application.Services;namespace WAID.Infrastructure.Persistence;public sealed class SqliteReliabilityTimelineRepository(WaidDatabase database):IReliabilityTimelineRepository
{private static readonly JsonSerializerOptions Json=new(JsonSerializerDefaults.Web);public async Task ReplaceAsync(ReliabilityTimelineProjection projection,CancellationToken token){await using var c=database.OpenConnection();await using var tx=await c.BeginTransactionAsync(token);try{await Exec(c,(Microsoft.Data.Sqlite.SqliteTransaction)tx,"DELETE FROM timeline_incidents",token);await Exec(c,(Microsoft.Data.Sqlite.SqliteTransaction)tx,"DELETE FROM timeline_events",token);foreach(var x in projection.Events){await using var q=c.CreateCommand();q.Transaction=(Microsoft.Data.Sqlite.SqliteTransaction)tx;q.CommandText="INSERT INTO timeline_events(id,occurred_utc,category,event_json)VALUES($id,$time,$category,$json)";q.Parameters.AddWithValue("$id",x.Id);q.Parameters.AddWithValue("$time",x.OccurredAtUtc.ToString("O"));q.Parameters.AddWithValue("$category",x.Kind.ToString());q.Parameters.AddWithValue("$json",JsonSerializer.Serialize(x,Json));await q.ExecuteNonQueryAsync(token);}foreach(var x in projection.Incidents){await using var q=c.CreateCommand();q.Transaction=(Microsoft.Data.Sqlite.SqliteTransaction)tx;q.CommandText="INSERT INTO timeline_incidents(id,started_utc,ended_utc,incident_json)VALUES($id,$start,$end,$json)";q.Parameters.AddWithValue("$id",x.Id);q.Parameters.AddWithValue("$start",x.StartedAtUtc.ToString("O"));q.Parameters.AddWithValue("$end",x.EndedAtUtc.ToString("O"));q.Parameters.AddWithValue("$json",JsonSerializer.Serialize(x,Json));await q.ExecuteNonQueryAsync(token);}await using(var state=c.CreateCommand()){state.Transaction=(Microsoft.Data.Sqlite.SqliteTransaction)tx;state.CommandText="INSERT INTO timeline_projection_state(id,projection_version,grouping_version,generated_utc)VALUES(1,$p,$g,$time) ON CONFLICT(id) DO UPDATE SET projection_version=$p,grouping_version=$g,generated_utc=$time";state.Parameters.AddWithValue("$p",projection.ProjectionVersion);state.Parameters.AddWithValue("$g",projection.GroupingVersion);state.Parameters.AddWithValue("$time",projection.GeneratedAtUtc.ToString("O"));await state.ExecuteNonQueryAsync(token);}await tx.CommitAsync(token);}catch{await tx.RollbackAsync(CancellationToken.None);throw;}}
 public async Task<TimelinePage>QueryAsync(TimelineQuery query,CancellationToken token){query.Validate();await using var c=database.OpenConnection();var where=new List<string>();if(query.FromUtc is not null)where.Add("occurred_utc>=$from");if(query.ToUtc is not null)where.Add("occurred_utc<=$to");if(query.Kind is not null)where.Add("category=$category");if(!string.IsNullOrWhiteSpace(query.Search))where.Add("event_json LIKE $search ESCAPE '\\'");var clause=where.Count==0?"":$" WHERE {string.Join(" AND ",where)}";await using var count=c.CreateCommand();count.CommandText="SELECT COUNT(*) FROM timeline_events"+clause;Parameters(count,query);var total=Convert.ToInt32(await count.ExecuteScalarAsync(token));await using var q=c.CreateCommand();q.CommandText="SELECT event_json FROM timeline_events"+clause+" ORDER BY occurred_utc DESC,id ASC LIMIT $limit OFFSET $offset";Parameters(q,query);q.Parameters.AddWithValue("$limit",query.PageSize);q.Parameters.AddWithValue("$offset",query.Page*query.PageSize);var items=new List<ReliabilityTimelineEvent>();await using var r=await q.ExecuteReaderAsync(token);while(await r.ReadAsync(token))items.Add(JsonSerializer.Deserialize<ReliabilityTimelineEvent>(r.GetString(0),Json)??throw new InvalidDataException("Invalid timeline event."));return new(items,query.Page,query.PageSize,total);}
 public async Task<ReliabilityIncident?>GetIncidentAsync(string id,CancellationToken token){if(string.IsNullOrWhiteSpace(id)||id.Length>100)throw new ArgumentException("Invalid incident id.",nameof(id));await using var c=database.OpenConnection();await using var q=c.CreateCommand();q.CommandText="SELECT incident_json FROM timeline_incidents WHERE id=$id";q.Parameters.AddWithValue("$id",id);var json=await q.ExecuteScalarAsync(token)as string;return json is null?null:JsonSerializer.Deserialize<ReliabilityIncident>(json,Json);}
 public async Task<IReadOnlyList<ReliabilityIncident>>GetRecentIncidentsAsync(int count,CancellationToken token){if(count is<1 or>500)throw new ArgumentOutOfRangeException(nameof(count));var items=new List<ReliabilityIncident>();await using var c=database.OpenConnection();await using var q=c.CreateCommand();q.CommandText="SELECT incident_json FROM timeline_incidents ORDER BY started_utc DESC,id ASC LIMIT $count";q.Parameters.AddWithValue("$count",count);await using var r=await q.ExecuteReaderAsync(token);while(await r.ReadAsync(token))items.Add(JsonSerializer.Deserialize<ReliabilityIncident>(r.GetString(0),Json)??throw new InvalidDataException("Invalid timeline incident."));return items;}
 private static void Parameters(Microsoft.Data.Sqlite.SqliteCommand q,TimelineQuery x){if(x.FromUtc is not null)q.Parameters.AddWithValue("$from",x.FromUtc.Value.ToUniversalTime().ToString("O"));if(x.ToUtc is not null)q.Parameters.AddWithValue("$to",x.ToUtc.Value.ToUniversalTime().ToString("O"));if(x.Kind is not null)q.Parameters.AddWithValue("$category",x.Kind.ToString());if(!string.IsNullOrWhiteSpace(x.Search))q.Parameters.AddWithValue("$search","%"+x.Search.Replace("\\","\\\\").Replace("%","\\%").Replace("_","\\_")+"%");}private static async Task Exec(Microsoft.Data.Sqlite.SqliteConnection c,Microsoft.Data.Sqlite.SqliteTransaction tx,string sql,CancellationToken t){await using var q=c.CreateCommand();q.Transaction=tx;q.CommandText=sql;await q.ExecuteNonQueryAsync(t);}}
